package main

import (
	"fmt"
	"math"
	"math/rand"
	"sort"
	"strings"
)

// ==================================================
// Mission 1: Inference — BPModel 텍스트 생성
//
// 샘플링 전략:
//   Greedy    : argmax (결정적, 반복 위험)
//   Top-K     : 상위 K개 후보에서 확률 샘플링
//   Nucleus   : 누적 확률 P(top-p) 이내 후보에서 샘플링
//   Temperature : softmax 분포 sharpening/smoothing
// ==================================================

// ─────────────────────────────────────────────────
// 샘플링 헬퍼
// ─────────────────────────────────────────────────

// applyTemperature: logits에 온도 적용 후 softmax
func applyTemperature(logits []float64, temp float64) []float64 {
	if temp <= 0 {
		temp = 1.0
	}
	scaled := make([]float64, len(logits))
	for i, v := range logits {
		scaled[i] = v / temp
	}
	return softmax1D(scaled)
}

// topKSample: 상위 K개 후보에서 확률적 샘플링
func topKSample(probs []float64, k int) int {
	type tv struct{ idx int; p float64 }
	cands := make([]tv, len(probs))
	for i, p := range probs {
		cands[i] = tv{i, p}
	}
	sort.Slice(cands, func(i, j int) bool { return cands[i].p > cands[j].p })
	if k > len(cands) {
		k = len(cands)
	}
	cands = cands[:k]

	// 재정규화
	sum := 0.0
	for _, c := range cands { sum += c.p }
	r := rand.Float64() * sum
	cum := 0.0
	for _, c := range cands {
		cum += c.p
		if r <= cum {
			return c.idx
		}
	}
	return cands[0].idx
}

// nucleusSample: top-p (nucleus) 샘플링
func nucleusSample(probs []float64, p float64) int {
	type tv struct{ idx int; prob float64 }
	cands := make([]tv, len(probs))
	for i, prob := range probs {
		cands[i] = tv{i, prob}
	}
	sort.Slice(cands, func(i, j int) bool { return cands[i].prob > cands[j].prob })

	// 누적 확률이 p를 넘는 최소 집합
	cum := 0.0
	cut := len(cands)
	for i, c := range cands {
		cum += c.prob
		if cum >= p {
			cut = i + 1
			break
		}
	}
	nucleus := cands[:cut]

	sum := 0.0
	for _, c := range nucleus { sum += c.prob }
	r := rand.Float64() * sum
	acc := 0.0
	for _, c := range nucleus {
		acc += c.prob
		if r <= acc {
			return c.idx
		}
	}
	return nucleus[0].idx
}

// greedySample: argmax
func greedySample(probs []float64) int {
	best, bestP := 0, probs[0]
	for i, p := range probs {
		if p > bestP {
			best, bestP = i, p
		}
	}
	return best
}

// ─────────────────────────────────────────────────
// BPModel.Generate — 핵심 생성 루프
// ─────────────────────────────────────────────────

type SamplingConfig struct {
	Method      string  // "greedy" | "topk" | "nucleus"
	Temperature float64 // 0.1 ~ 2.0
	TopK        int     // top-k k 값
	TopP        float64 // nucleus p 값 (0 ~ 1)
	MaxTokens   int
}

func DefaultConfig() SamplingConfig {
	return SamplingConfig{
		Method:      "nucleus",
		Temperature: 0.8,
		TopK:        40,
		TopP:        0.9,
		MaxTokens:   200,
	}
}

// Generate: 프롬프트 토큰 리스트 → 생성된 토큰 리스트
func (m *BPModel) Generate(prompt []int, cfg SamplingConfig) []int {
	ctx := make([]int, len(prompt))
	copy(ctx, prompt)

	generated := []int{}
	maxCtx := 128 // 최대 컨텍스트 길이

	for i := 0; i < cfg.MaxTokens; i++ {
		// 컨텍스트 윈도우 제한
		input := ctx
		if len(input) > maxCtx {
			input = input[len(input)-maxCtx:]
		}

		logits, _ := m.forwardBP(input)
		probs := applyTemperature(logits, cfg.Temperature)

		var next int
		switch cfg.Method {
		case "greedy":
			next = greedySample(probs)
		case "topk":
			next = topKSample(probs, cfg.TopK)
		default: // nucleus
			next = nucleusSample(probs, cfg.TopP)
		}

		ctx = append(ctx, next)
		generated = append(generated, next)
	}
	return generated
}

// ─────────────────────────────────────────────────
// 토큰 → 문자열 변환
// ─────────────────────────────────────────────────

func tokensToString(tokens []int, vocab map[string]int) string {
	// 역방향 vocab
	rev := make(map[int]string, len(vocab))
	for ch, id := range vocab {
		rev[id] = ch
	}
	var sb strings.Builder
	for _, t := range tokens {
		if ch, ok := rev[t]; ok {
			sb.WriteString(ch)
		} else {
			sb.WriteString("?")
		}
	}
	return sb.String()
}

func stringToTokens(s string, vocab map[string]int) []int {
	tokens := []int{}
	for _, ch := range s {
		if id, ok := vocab[string(ch)]; ok {
			tokens = append(tokens, id)
		} else {
			tokens = append(tokens, 0) // <UNK>
		}
	}
	return tokens
}

// ─────────────────────────────────────────────────
// generateBP: 학습 후 즉시 호출되는 데모
// ─────────────────────────────────────────────────

func generateBP(model *BPModel, vocab map[string]int) {
	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("🔤 Mission 1: Text Generation (Inference)")
	fmt.Println("══════════════════════════════════════════════════════════════\n")

	prompts := []struct {
		text string
		desc string
	}{
		{"fn ", "FreeLang 함수 선언"},
		{"let ", "변수 선언"},
		{"// ", "주석"},
		{"FreeLang", "언어 이름"},
		{"if ", "조건문"},
	}

	configs := []struct {
		cfg  SamplingConfig
		name string
	}{
		{SamplingConfig{"greedy",  1.0, 0,  0,   80}, "Greedy"},
		{SamplingConfig{"topk",    0.8, 20, 0,   80}, "Top-K(k=20, t=0.8)"},
		{SamplingConfig{"nucleus", 0.8, 0,  0.9, 80}, "Nucleus(p=0.9, t=0.8)"},
		{SamplingConfig{"nucleus", 1.2, 0,  0.95, 80}, "Nucleus(p=0.95, t=1.2) creative"},
	}

	for _, pr := range prompts {
		promptToks := stringToTokens(pr.text, vocab)
		if len(promptToks) == 0 {
			continue
		}

		fmt.Printf("┌─ 프롬프트: %q (%s)\n", pr.text, pr.desc)
		for _, c := range configs {
			gen := model.Generate(promptToks, c.cfg)
			full := tokensToString(append(promptToks, gen...), vocab)
			// 출력 정리: 제어문자 제거, 100자 제한
			clean := cleanOutput(full, 100)
			fmt.Printf("│  [%-32s] %s\n", c.name, clean)
		}
		fmt.Println("└──────────────────────────────────────────────────────────")
		fmt.Println()
	}

	// Top-1 확률 분포 분석
	fmt.Println("📊 다음 토큰 확률 분포 (프롬프트: \"fn \"):")
	sample := stringToTokens("fn ", vocab)
	if len(sample) > 0 {
		logits, _ := model.forwardBP(sample)
		probs := applyTemperature(logits, 1.0)
		showTopTokens(probs, vocab, 10)
	}
}

// cleanOutput: 제어문자 제거 + 길이 제한
func cleanOutput(s string, maxLen int) string {
	var sb strings.Builder
	count := 0
	for _, ch := range s {
		if count >= maxLen {
			sb.WriteString("...")
			break
		}
		// 가시 가능한 문자만 출력
		if ch == '\n' {
			sb.WriteString("↵")
		} else if ch == '\t' {
			sb.WriteString("→")
		} else if ch >= 32 {
			sb.WriteRune(ch)
		}
		count++
	}
	return sb.String()
}

// showTopTokens: 다음 토큰 상위 N개 확률 표시
func showTopTokens(probs []float64, vocab map[string]int, n int) {
	rev := make(map[int]string, len(vocab))
	for ch, id := range vocab {
		rev[id] = ch
	}

	type tv struct{ idx int; p float64 }
	all := make([]tv, len(probs))
	for i, p := range probs { all[i] = tv{i, p} }
	sort.Slice(all, func(i, j int) bool { return all[i].p > all[j].p })

	entropy := 0.0
	for _, p := range probs {
		if p > 1e-10 {
			entropy -= p * math.Log2(p)
		}
	}

	fmt.Printf("  엔트로피: %.2f bits (최대 %.2f bits)\n", entropy, math.Log2(float64(len(probs))))
	fmt.Println("  순위  토큰      확률")
	fmt.Println("  ────  ────────  ──────")
	for i := 0; i < n && i < len(all); i++ {
		ch := rev[all[i].idx]
		if ch == "\n" { ch = "\\n" }
		if ch == "\t" { ch = "\\t" }
		if ch == " "  { ch = "·" }
		bar := strings.Repeat("█", int(all[i].p*40))
		fmt.Printf("  %3d.  %-8s  %.4f  %s\n", i+1, ch, all[i].p, bar)
	}
	fmt.Println()
}

package main

import (
	"fmt"
	"os"
)

// ==================================================
// FreeLang GPT - Training Driver
// Priority 2 (SGD): 안정적인 기준선
// Priority 3 (Adam): hybrid 구현
// ==================================================

func main() {
	mode := "priority2"

	// 커맨드라인 인자로 모드 선택
	// Termux 환경: Args[1]이 절대경로로 주입되는 경우가 있어 '/'로 시작하지 않는 인자를 사용
	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if len(arg) > 0 && arg[0] != '/' {
			mode = arg
			break
		}
	}

	switch mode {
	case "priority2":
		trainWithRealLoss()

	case "priority3":
		testAdamOptimizer()
		fmt.Println("")
		fmt.Println("🔄 Starting Priority 3 training with Adam...")
		fmt.Println("")
		trainWithAdam()

	case "test-optimizer":
		TestOptimizers()

	case "validate-adam":
		testAdamOptimizer()

	case "collect-md":
		testMDCollection()

	case "phase4":
		trainWithAttention()

	case "phase5":
		trainTransformer()

	case "phase6":
		trainTransformerV2()

	case "phase7":
		trainBP()

	case "generate":
		// 독립 실행: 학습 후 생성만 데모 (빠른 테스트)
		tokens, vocab, err := loadCorpus("data/corpus.txt", 200_000, 300)
		if err != nil {
			fmt.Printf("❌ corpus.txt: %v\n", err)
			return
		}
		d, ffn, numHeads := 128, 512, 4
		model := newBPModel(len(vocab), d, ffn, numHeads)
		// 미니 학습 (3 epoch, 빠른 확인용)
		adam := newBPAdams(0.0003, len(vocab), d, ffn)
		for epoch := 1; epoch <= 3; epoch++ {
			for batch := 0; batch < 200; batch++ {
				if len(tokens) <= 65 { break }
				start := batch % (len(tokens) - 65)
				seq := tokens[start : start+64]
				target := tokens[start+64]
				logits, cache := model.forwardBP(seq)
				probs := softmax1D(logits)
				dLogits := make([]float64, len(probs))
				copy(dLogits, probs)
				if target < len(dLogits) { dLogits[target] -= 1.0 }
				model.backwardStep(seq, target, cache, dLogits, adam)
			}
			fmt.Printf("Quick epoch %d/3\n", epoch)
		}
		generateBP(model, vocab)

	default:
		fmt.Println("\n╔════════════════════════════════════════════════════════╗")
		fmt.Println("║  FreeLang GPT - Training Mode Selector                ║")
		fmt.Println("╚════════════════════════════════════════════════════════╝\n")
		fmt.Println("Usage: go run . [mode]")
		fmt.Println("")
		fmt.Println("Modes:")
		fmt.Println("  priority2          - SGD (5 epochs, stable baseline)")
		fmt.Println("  priority3          - Adam (20 epochs, hybrid approach)")
		fmt.Println("  test-optimizer     - Unit tests for optimizers")
		fmt.Println("")
		fmt.Println("Default: priority2")
		fmt.Println("")
		fmt.Println("Running Priority 2 (default)...")
		fmt.Println("")
		trainWithRealLoss()
	}
}

