// ==================================================
// Mission 2: BPModel 저장 / 로드 (바이너리 포맷)
//
// 포맷 (순서대로):
//   Header  : magic(4B) + version(4B)
//   Config  : vocabSize, dModel, dFFn, numHeads  (각 int32)
//   Weights : embedding, Wq, Wk, Wv, Wo,
//             ln1Scale, ln1Bias,
//             W1, b1, W2, b2,
//             ln2Scale, ln2Bias,
//             proj
//             (모두 little-endian float64)
// ==================================================

const (
	bpMagic   = 0x465F4250 // "FP_B" (FreeLang Phase-7 BP)
	bpVersion = 1
)

// ─────────────────────────────────────────────────
// 저장
// ─────────────────────────────────────────────────

func (m *BPModel) Save(path string) error {
	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create %s: %w", path, err)
	}
	defer f.Close()

	w := &binWriter{f: f}

	// Header
	w.u32(bpMagic)
	w.u32(bpVersion)

	// Config
	w.i32(int32(m.vocabSize))
	w.i32(int32(m.dModel))
	w.i32(int32(m.dFFn))
	w.i32(int32(m.numHeads))

	// Weights
	w.mat(m.embedding)
	w.mat(m.Wq)
	w.mat(m.Wk)
	w.mat(m.Wv)
	w.mat(m.Wo)
	w.vec(m.ln1Scale)
	w.vec(m.ln1Bias)
	w.mat(m.W1)
	w.vec(m.b1)
	w.mat(m.W2)
	w.vec(m.b2)
	w.vec(m.ln2Scale)
	w.vec(m.ln2Bias)
	w.mat(m.proj)

	return w.err
}

// ─────────────────────────────────────────────────
// 로드
// ─────────────────────────────────────────────────

func LoadBPModel(path string) (*BPModel, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", path, err)
	}
	defer f.Close()

	r := &binReader{f: f}

	// Header
	magic := r.u32()
	ver   := r.u32()
	if r.err != nil {
		return nil, fmt.Errorf("read header: %w", r.err)
	}
	if magic != bpMagic {
		return nil, fmt.Errorf("invalid magic: 0x%X (want 0x%X)", magic, bpMagic)
	}
	if ver != bpVersion {
		return nil, fmt.Errorf("unsupported version: %d", ver)
	}

	// Config
	vocabSize := int(r.i32())
	dModel    := int(r.i32())
	dFFn      := int(r.i32())
	numHeads  := int(r.i32())
	if r.err != nil {
		return nil, fmt.Errorf("read config: %w", r.err)
	}

	m := &BPModel{
		vocabSize: vocabSize,
		dModel:    dModel,
		dFFn:      dFFn,
		numHeads:  numHeads,
		dHead:     dModel / numHeads,
	}

	// Weights
	m.embedding = r.mat(vocabSize, dModel)
	m.Wq        = r.mat(dModel,    dModel)
	m.Wk        = r.mat(dModel,    dModel)
	m.Wv        = r.mat(dModel,    dModel)
	m.Wo        = r.mat(dModel,    dModel)
	m.ln1Scale  = r.vec(dModel)
	m.ln1Bias   = r.vec(dModel)
	m.W1        = r.mat(dModel,    dFFn)
	m.b1        = r.vec(dFFn)
	m.W2        = r.mat(dFFn,      dModel)
	m.b2        = r.vec(dModel)
	m.ln2Scale  = r.vec(dModel)
	m.ln2Bias   = r.vec(dModel)
	m.proj      = r.mat(dModel,    vocabSize)

	if r.err != nil {
		return nil, fmt.Errorf("read weights: %w", r.err)
	}
	return m, nil
}

// ─────────────────────────────────────────────────
// 바이너리 writer / reader 헬퍼
// ─────────────────────────────────────────────────

type binWriter struct {
	f   *os.File
	err error
}

func (w *binWriter) u32(v uint32) {
	if w.err != nil { return }
	w.err = binary.Write(w.f, binary.LittleEndian, v)
}

func (w *binWriter) i32(v int32) {
	if w.err != nil { return }
	w.err = binary.Write(w.f, binary.LittleEndian, v)
}

func (w *binWriter) f64(v float64) {
	if w.err != nil { return }
	w.err = binary.Write(w.f, binary.LittleEndian, v)
}

func (w *binWriter) vec(v []float64) {
	for _, x := range v { w.f64(x) }
}

func (w *binWriter) mat(m [][]float64) {
	for _, row := range m { w.vec(row) }
}

// ─────────────────────────────────────────────────

type binReader struct {
	f   io.Reader
	err error
}

func (r *binReader) u32() uint32 {
	if r.err != nil { return 0 }
	var v uint32
	r.err = binary.Read(r.f, binary.LittleEndian, &v)
	return v
}

func (r *binReader) i32() int32 {
	if r.err != nil { return 0 }
	var v int32
	r.err = binary.Read(r.f, binary.LittleEndian, &v)
	return v
}

func (r *binReader) f64() float64 {
	if r.err != nil { return 0 }
	var v float64
	r.err = binary.Read(r.f, binary.LittleEndian, &v)
	return v
}

func (r *binReader) vec(n int) []float64 {
	v := make([]float64, n)
	for i := range v { v[i] = r.f64() }
	return v
}

func (r *binReader) mat(rows, cols int) [][]float64 {
	m := make([][]float64, rows)
	for i := range m { m[i] = r.vec(cols) }
	return m
}

