	"fmt"
	"os"
)

// ==================================================
// FreeLang GPT - Training Driver
// Priority 2 (SGD): 안정적인 기준선
// Priority 3 (Adam): hybrid 구현
// ==================================================

func main() {
	mode := "priority2"

	// 커맨드라인 인자로 모드 선택
	// Termux 환경: Args[1]이 절대경로로 주입되는 경우가 있어 '/'로 시작하지 않는 인자를 사용
	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if len(arg) > 0 && arg[0] != '/' {
			mode = arg
			break
		}
	}

	switch mode {
	case "priority2":
		trainWithRealLoss()

	case "priority3":
		testAdamOptimizer()
		fmt.Println("")
		fmt.Println("🔄 Starting Priority 3 training with Adam...")
		fmt.Println("")
		trainWithAdam()

	case "test-optimizer":
		TestOptimizers()

	case "validate-adam":
		testAdamOptimizer()

	case "collect-md":
		testMDCollection()

	case "phase4":
		trainWithAttention()

	case "phase5":
		trainTransformer()

	case "phase6":
		trainTransformerV2()

	case "phase7":
		trainBP()

	case "generate":
		// 독립 실행: 학습 후 생성만 데모 (빠른 테스트)
		tokens, vocab, err := loadCorpus("data/corpus.txt", 200_000, 300)
		if err != nil {
			fmt.Printf("❌ corpus.txt: %v\n", err)
			return
		}
		d, ffn, numHeads := 128, 512, 4
		model := newBPModel(len(vocab), d, ffn, numHeads)
		// 미니 학습 (3 epoch, 빠른 확인용)
		adam := newBPAdams(0.0003, len(vocab), d, ffn)
		for epoch := 1; epoch <= 3; epoch++ {
			for batch := 0; batch < 200; batch++ {
				if len(tokens) <= 65 { break }
				start := batch % (len(tokens) - 65)
				seq := tokens[start : start+64]
				target := tokens[start+64]
				logits, cache := model.forwardBP(seq)
				probs := softmax1D(logits)
				dLogits := make([]float64, len(probs))
				copy(dLogits, probs)
				if target < len(dLogits) { dLogits[target] -= 1.0 }
				model.backwardStep(seq, target, cache, dLogits, adam)
			}
			fmt.Printf("Quick epoch %d/3\n", epoch)
		}
		generateBP(model, vocab)

	default:
		fmt.Println("\n╔════════════════════════════════════════════════════════╗")
		fmt.Println("║  FreeLang GPT - Training Mode Selector                ║")
		fmt.Println("╚════════════════════════════════════════════════════════╝\n")
		fmt.Println("Usage: go run . [mode]")
		fmt.Println("")
		fmt.Println("Modes:")
		fmt.Println("  priority2          - SGD (5 epochs, stable baseline)")
		fmt.Println("  priority3          - Adam (20 epochs, hybrid approach)")
		fmt.Println("  test-optimizer     - Unit tests for optimizers")
		fmt.Println("")
		fmt.Println("Default: priority2")
		fmt.Println("")
		fmt.Println("Running Priority 2 (default)...")
		fmt.Println("")
		trainWithRealLoss()
	}
}

