func runREPL(model *BPModel, vocab map[string]int) {
	cfg := SamplingConfig{
		Method:    "nucleus",
		Temperature: 0.9,
		TopK:      20,
		TopP:      0.9,
		MaxTokens: 80,
	}

	fmt.Println()
	fmt.Println("╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT — Interactive REPL (Mission 3)               ║")
	fmt.Println("║  저장된 모델로 즉시 텍스트 생성                            ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝")
	fmt.Printf("  모델: vocab=%d, d=%d, heads=%d\n", model.vocabSize, model.dModel, model.numHeads)
	fmt.Println("  :help 로 명령어 확인 | :q 로 종료")
	fmt.Println()

	scanner := bufio.NewScanner(os.Stdin)
	for {
		fmt.Print(">>> ")
		if !scanner.Scan() {
			break
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}

		// 명령어
		if strings.HasPrefix(line, ":") {
			parts := strings.Fields(line)
			cmd := parts[0]
			arg := ""
			if len(parts) > 1 {
				arg = parts[1]
			}

			switch cmd {
			case ":q", ":quit", ":exit":
				fmt.Println("👋 종료합니다.")
				return

			case ":help":
				printReplHelp()

			case ":info":
				printReplInfo(cfg)

			case ":method":
				switch arg {
				case "greedy", "topk", "nucleus":
					cfg.Method = arg
					fmt.Printf("  method = %s\n", cfg.Method)
				default:
					fmt.Println("  사용 가능: greedy | topk | nucleus")
				}

			case ":temp":
				if v, err := strconv.ParseFloat(arg, 64); err == nil && v > 0 {
					cfg.Temperature = v
					fmt.Printf("  temperature = %.2f\n", cfg.Temperature)
				} else {
					fmt.Println("  사용법: :temp 0.8  (0.1 ~ 2.0)")
