				} else {
					fmt.Println("  사용법: :topk 20")
				}

			case ":topp":
				if v, err := strconv.ParseFloat(arg, 64); err == nil && v > 0 && v <= 1 {
					cfg.TopP = v
					fmt.Printf("  top-p = %.2f\n", cfg.TopP)
				} else {
					fmt.Println("  사용법: :topp 0.9  (0.0 ~ 1.0)")
				}

			case ":tokens":
				if v, err := strconv.Atoi(arg); err == nil && v > 0 {
					cfg.MaxTokens = v
					fmt.Printf("  max_tokens = %d\n", cfg.MaxTokens)
				} else {
					fmt.Println("  사용법: :tokens 100")
				}

			default:
				fmt.Printf("  알 수 없는 명령: %s  (:help 참고)\n", cmd)
			}
			fmt.Println()
			continue
		}

