		full := tokensToString(append(promptToks, gen...), vocab)
		clean := cleanOutput(full, 200)

		fmt.Println()
		fmt.Println("┌─ 생성 결과 ─────────────────────────────────────────────")
		fmt.Printf("│  %s\n", clean)
		fmt.Println("└──────────────────────────────────────────────────────────")

		// 다음 토큰 Top-5 확률
		logits, _ := model.forwardBP(promptToks)
		probs := applyTemperature(logits, cfg.Temperature)
		fmt.Printf("  다음 토큰 Top-5 (method=%s, temp=%.1f):\n", cfg.Method, cfg.Temperature)
