// BPModel Full backprop Transformer (1-layer)
type BPModel struct {
	vocabSize int
	dModel    int
	dFFn      int
	numHeads  int
	dHead     int

	embedding [][]float64 // [vocab, d]
	Wq        [][]float64 // [d, d]
	Wk        [][]float64
	Wv        [][]float64
	Wo        [][]float64
	ln1Scale  []float64
	ln1Bias   []float64
	W1        [][]float64 // [d, ffn]
	b1        []float64
	W2        [][]float64 // [ffn, d]
	b2        []float64
	ln2Scale  []float64
	ln2Bias   []float64
	proj      [][]float64 // [d, vocab]
}

func newBPModel(vocabSize, d, ffn, numHeads int) *BPModel {
	scale  := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))
	return &BPModel{
		vocabSize: vocabSize,
		dModel:    d,
		dFFn:      ffn,
		numHeads:  numHeads,
		dHead:     d / numHeads,
		embedding: make2DRand(vocabSize, d, vScale),
		Wq:        make2DRand(d, d, scale),
		Wk:        make2DRand(d, d, scale),
		Wv:        make2DRand(d, d, scale),
		Wo:        make2DRand(d, d, scale),
		ln1Scale:  onesVec(d),
		ln1Bias:   zerosVec(d),
		W1:        make2DRand(d, ffn, fScale),
		b1:        zerosVec(ffn),
		W2:        make2DRand(ffn, d, fScale),
		b2:        zerosVec(d),
		ln2Scale:  onesVec(d),
		ln2Bias:   zerosVec(d),
		proj:      make2DRand(d, vocabSize, vScale),
	}
}

// ──────────────────────────────────────────────────────────
// LayerNorm helpers
// ──────────────────────────────────────────────────────────

func layerNormFull(x, scale, bias []float64) (out []float64, mean, invStd float64) {
	n := len(x)
	for _, v := range x { mean += v }
	mean /= float64(n)
	variance := 0.0
	for _, v := range x {
		d := v - mean
		variance += d * d
	}
	variance /= float64(n)
	invStd = 1.0 / math.Sqrt(variance+1e-5)
	out = make([]float64, n)
	for i, v := range x {
		out[i] = scale[i]*(v-mean)*invStd + bias[i]
	}
	return
}

// layerNormBackward: 정확한 수식
// dX = invStd/n * (n*dOut*scale - sum(dOut*scale) - xHat*sum(dOut*scale*xHat))
func layerNormBackward(dOut, x, scale []float64, mean, invStd float64) (dX, dScale, dBias []float64) {
	n := len(dOut)
	dScale = make([]float64, n)
	dBias  = make([]float64, n)
	dX     = make([]float64, n)

	xHat := make([]float64, n)
	for i := range x { xHat[i] = (x[i] - mean) * invStd }

	sumDS, sumDSX := 0.0, 0.0
	for i := range dOut {
		dScale[i] = dOut[i] * xHat[i]
		dBias[i]  = dOut[i]
		sumDS  += dOut[i] * scale[i]
		sumDSX += dOut[i] * scale[i] * xHat[i]
	}
	for i := range dOut {
		dX[i] = invStd / float64(n) * (float64(n)*dOut[i]*scale[i] - sumDS - xHat[i]*sumDSX)
	}
	return
}

// ──────────────────────────────────────────────────────────
// GELU & derivative
// ──────────────────────────────────────────────────────────

// geluGrad: dGELU/dx 정확한 수식
func geluGrad(x float64) float64 {
	c := math.Sqrt(2.0 / math.Pi)
	inner := c * (x + 0.044715*x*x*x)
	tanh  := math.Tanh(inner)
	dInner := c * (1.0 + 3*0.044715*x*x)
	return 0.5*(1+tanh) + 0.5*x*(1-tanh*tanh)*dInner
}

// ──────────────────────────────────────────────────────────
// Forward Pass
// ──────────────────────────────────────────────────────────

