package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
)

// ==================================================
// BPE Tokenizer (Byte-Pair Encoding)
//
// 학습: 텍스트 → 빈도 기반 머지 → vocab
// 인코딩: 텍스트 → []int
// 디코딩: []int → 텍스트
// ==================================================

type BPETokenizer struct {
	Vocab   map[string]int // token → id
	RevVocab map[int]string // id → token
	Merges  []BPEMerge     // 머지 규칙 (순서 중요)
}

type BPEMerge struct {
	A, B   string
	Result string
}

type BPEConfig struct {
	Vocab   map[string]int `json:"vocab"`
	Merges  [][]string     `json:"merges"` // [[a, b], ...]
}

// ─────────────────────────────────────────────────
// 학습
// ─────────────────────────────────────────────────

func TrainBPE(text string, vocabSize int) *BPETokenizer {
	fmt.Printf("[BPE] 학습 시작: 목표 vocab=%d\n", vocabSize)

	// 1) 초기 vocab: 모든 바이트(문자) + 특수 토큰
	baseVocab := map[string]int{}
	baseVocab["<UNK>"] = 0
	baseVocab["<PAD>"] = 1
	baseVocab["<BOS>"] = 2
	baseVocab["<EOS>"] = 3
	nextID := 4

	for _, ch := range text {
		s := string(ch)
		if _, ok := baseVocab[s]; !ok {
			baseVocab[s] = nextID
			nextID++
		}
	}
	fmt.Printf("[BPE] 초기 문자 vocab: %d\n", len(baseVocab))

	// 2) 단어 분리 (공백 기준, 각 문자 사이 공백)
	words := tokenizeWords(text)
	wordFreq := map[string]int{}
	for _, w := range words {
		wordFreq[w]++
	}

	// 단어를 문자 시퀀스로 변환
	// "hello" → ["h","e","l","l","o","</w>"]
	wordSeqs := map[string][]string{}
	for w := range wordFreq {
		wordSeqs[w] = splitWord(w)
	}

	merges := []BPEMerge{}
	vocab := map[string]int{}
	for k, v := range baseVocab {
		vocab[k] = v
	}

	// 3) 머지 반복
	target := vocabSize - len(baseVocab)
	if target < 0 { target = 0 }

	for i := 0; i < target; i++ {
		// 가장 빈번한 bigram 찾기
		pairs := countPairs(wordSeqs, wordFreq)
		if len(pairs) == 0 {
			break
		}
		best := bestPair(pairs)
		if pairs[best] < 2 {
			break
		}

		// 머지 실행
		merged := best[0] + best[1]
		merges = append(merges, BPEMerge{best[0], best[1], merged})
		if _, ok := vocab[merged]; !ok {
			vocab[merged] = nextID
			nextID++
		}

		// wordSeqs 갱신
		for w := range wordSeqs {
			wordSeqs[w] = applyMerge(wordSeqs[w], best[0], best[1], merged)
		}

		if (i+1)%500 == 0 {
			fmt.Printf("[BPE] 머지 %d/%d, vocab=%d\n", i+1, target, len(vocab))
		}
	}

	fmt.Printf("[BPE] 완료: vocab=%d, merges=%d\n", len(vocab), len(merges))

	rev := make(map[int]string, len(vocab))
	for k, v := range vocab { rev[v] = k }

	return &BPETokenizer{
		Vocab:    vocab,
		RevVocab: rev,
		Merges:   merges,
	}
}

// ─────────────────────────────────────────────────
// 인코딩 / 디코딩
// ─────────────────────────────────────────────────

func (t *BPETokenizer) Encode(text string) []int {
	words := tokenizeWords(text)
	ids := []int{}
	for _, w := range words {
		seq := splitWord(w)
		// 머지 적용
		for _, m := range t.Merges {
			seq = applyMerge(seq, m.A, m.B, m.Result)
		}
		for _, tok := range seq {
			if id, ok := t.Vocab[tok]; ok {
				ids = append(ids, id)
			} else {
				ids = append(ids, 0) // <UNK>
			}
		}
	}
	return ids
}

func (t *BPETokenizer) Decode(ids []int) string {
	var sb strings.Builder
	for _, id := range ids {
		if tok, ok := t.RevVocab[id]; ok {
			// </w> → 공백으로 복원
			tok = strings.ReplaceAll(tok, "</w>", " ")
			sb.WriteString(tok)
		}
	}
	return sb.String()
}

func (t *BPETokenizer) VocabSize() int {
	return len(t.Vocab)
}

// ─────────────────────────────────────────────────
// 저장 / 로드
// ─────────────────────────────────────────────────

func (t *BPETokenizer) Save(path string) error {
	mergesRaw := make([][]string, len(t.Merges))
	for i, m := range t.Merges {
		mergesRaw[i] = []string{m.A, m.B}
	}
	cfg := BPEConfig{Vocab: t.Vocab, Merges: mergesRaw}
	data, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil { return err }
	return os.WriteFile(path, data, 0644)
}

func LoadBPETokenizer(path string) (*BPETokenizer, error) {
	data, err := os.ReadFile(path)
	if err != nil { return nil, err }
	var cfg BPEConfig
	if err := json.Unmarshal(data, &cfg); err != nil { return nil, err }

	merges := make([]BPEMerge, len(cfg.Merges))
	for i, m := range cfg.Merges {
		merges[i] = BPEMerge{m[0], m[1], m[0] + m[1]}
	}
	rev := make(map[int]string, len(cfg.Vocab))
	for k, v := range cfg.Vocab { rev[v] = k }

	return &BPETokenizer{Vocab: cfg.Vocab, RevVocab: rev, Merges: merges}, nil
}

// ─────────────────────────────────────────────────
// 내부 헬퍼
// ─────────────────────────────────────────────────

func tokenizeWords(text string) []string {
	// 공백/개행으로 분리
	return strings.FieldsFunc(text, func(r rune) bool {
		return r == ' ' || r == '\n' || r == '\t' || r == '\r'
	})
}

func splitWord(w string) []string {
	runes := []rune(w)
	out := make([]string, len(runes))
	for i, r := range runes {
		if i == len(runes)-1 {
			out[i] = string(r) + "</w>"
		} else {
			out[i] = string(r)
		}
	}
	return out
}

type pair [2]string

func countPairs(wordSeqs map[string][]string, wordFreq map[string]int) map[pair]int {
	counts := map[pair]int{}
	for w, seq := range wordSeqs {
		freq := wordFreq[w]
		for i := 0; i < len(seq)-1; i++ {
			p := pair{seq[i], seq[i+1]}
			counts[p] += freq
		}
	}
	return counts
}

func bestPair(counts map[pair]int) pair {
	type pv struct{ p pair; v int }
	all := make([]pv, 0, len(counts))
	for p, v := range counts { all = append(all, pv{p, v}) }
	sort.Slice(all, func(i, j int) bool {
		if all[i].v != all[j].v { return all[i].v > all[j].v }
		return all[i].p[0]+all[i].p[1] < all[j].p[0]+all[j].p[1]
	})
	return all[0].p
}

func applyMerge(seq []string, a, b, merged string) []string {
	out := []string{}
	i := 0
	for i < len(seq) {
		if i < len(seq)-1 && seq[i] == a && seq[i+1] == b {
			out = append(out, merged)
			i += 2
		} else {
			out = append(out, seq[i])
			i++
		}
	}
	return out
}

