package main

import (
	"fmt"
	"math"
	"math/rand"
	"os"
)

// ==================================================
// Phase 7B: BPE 토크나이저 기반 학습
//
// 문자 단위(300~500) → BPE 서브워드(3000)
// 더 풍부한 vocab → 의미 있는 텍스트 생성
// ==================================================

func trainBPE_mode() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 7B: BPE Tokenizer + BP Transformer                   ║")
	fmt.Println("║  vocab=3000 서브워드, 의미 있는 텍스트 생성 목표            ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	// 1) 코퍼스 읽기
	fmt.Println("[1/6] Loading corpus...")
	data, err := os.ReadFile("data/corpus.txt")
	if err != nil {
		fmt.Printf("❌ corpus.txt: %v\n", err)
		return
	}
	text := string(data)
	if len([]rune(text)) > 500_000 {
		runes := []rune(text)
		text = string(runes[:500_000])
	}
	fmt.Printf("✅ 읽기: %d 문자\n\n", len([]rune(text)))

	// 2) BPE 학습 또는 로드
	bpePath := "data/bpe_vocab.json"
	var tok *BPETokenizer

	if _, err := os.Stat(bpePath); err == nil {
		fmt.Printf("[2/6] BPE 로드: %s\n", bpePath)
		tok, err = LoadBPETokenizer(bpePath)
		if err != nil {
			fmt.Printf("❌ 로드 실패: %v → 재학습\n", err)
			tok = nil
		} else {
			fmt.Printf("✅ BPE 로드 완료: vocab=%d\n\n", tok.VocabSize())
		}
	}

	if tok == nil {
		fmt.Println("[2/6] BPE 학습 중 (vocab=3000)...")
		tok = TrainBPE(text, 3000)
		if err := tok.Save(bpePath); err != nil {
			fmt.Printf("⚠️  BPE 저장 실패: %v\n", err)
		} else {
			fmt.Printf("✅ BPE 저장: %s (vocab=%d)\n\n", bpePath, tok.VocabSize())
		}
	}

	// 3) 인코딩
	fmt.Println("[3/6] 인코딩...")
	tokens := tok.Encode(text)
	vocabSize := tok.VocabSize()
	fmt.Printf("✅ tokens=%d, vocab=%d\n\n", len(tokens), vocabSize)

	if len(tokens) < 100 {
		fmt.Println("❌ 토큰이 너무 적습니다.")
		return
	}

	// 4) 모델 생성
	d, ffn, numHeads := 128, 512, 4
	fmt.Println("[4/6] Creating BP Transformer...")
	model := newBPModel(vocabSize, d, ffn, numHeads)
	params := vocabSize*d + d*d*4 + d*ffn*2 + d*vocabSize
	fmt.Printf("✅ d=%d, heads=%d, FFN=%d, vocab=%d, params=~%dk\n\n",
		d, numHeads, ffn, vocabSize, params/1000)

	// 5) Adam
	fmt.Println("[5/6] Initializing Adam...")
	adam := newBPAdams(0.0003, vocabSize, d, ffn)
	fmt.Printf("✅ Adam ready\n\n")

	// 6) 학습
	seqLen     := 48
	epochs     := 20
	numBatches := 500
	warmup     := 500
	total      := epochs * numBatches

	fmt.Printf("[6/6] Training: seqLen=%d, epochs=%d, batch=%d\n", seqLen, epochs, numBatches)
	fmt.Println("══════════════════════════════════════════════════════════════")

	losses  := make([]float64, 0, epochs)
	bestPPL := math.MaxFloat64
	step    := 0

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0
		for b := 0; b < numBatches; b++ {
			step++
			if len(tokens) <= seqLen+1 { break }
			start := rand.Intn(len(tokens) - seqLen - 1)
			seq    := tokens[start : start+seqLen]
			target := tokens[start+seqLen]

			// LR warmup + cosine
			lr := 0.0003
			if step <= warmup {
				lr = 0.0003 * float64(step) / float64(warmup)
			} else {
				p := float64(step-warmup) / float64(total-warmup)
				lr = 0.0003 * 0.5 * (1 + math.Cos(math.Pi*p))
			}
			adam.setLR(lr)

			logits, cache := model.forwardBP(seq)
			probs := softmax1D(logits)
			loss  := -math.Log(probs[target] + 1e-10)
			epochLoss += loss

			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if target < len(dLogits) { dLogits[target] -= 1.0 }
			model.backwardStep(seq, target, cache, dLogits, adam)
		}

		avg := epochLoss / float64(numBatches)
		ppl := math.Exp(avg)
		losses = append(losses, avg)
		mark := ""
		if ppl < bestPPL { bestPPL = ppl; mark = " ★ best" }
		fmt.Printf("✅ Epoch %02d/%d: loss=%.4f  PPL=%.2f%s\n", epoch, epochs, avg, ppl, mark)
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp  := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 결과: %.2f → %.2f (Best: %.2f)\n", iPPL, fPPL, bestPPL)
		if imp > 0 { fmt.Printf("   개선: %.1f%% ✅\n\n", imp) } else { fmt.Printf("   악화: %.1f%% ⚠️\n\n", -imp) }
	}

	// 저장
	savePath := "data/bpe_model.bin"
	if err := model.Save(savePath); err != nil {
		fmt.Printf("⚠️  저장 실패: %v\n", err)
	} else {
		fi, _ := os.Stat(savePath)
		size := int64(0)
		if fi != nil { size = fi.Size() }
		fmt.Printf("💾 BPE 모델 저장: %s (%.1f MB)\n\n", savePath, float64(size)/1e6)
	}

	// 생성 데모 (BPE 디코딩)
	generateBPE(model, tok)
}

// ─────────────────────────────────────────────────
// BPE 기반 텍스트 생성
// ─────────────────────────────────────────────────

func generateBPE(model *BPModel, tok *BPETokenizer) {
	fmt.Println("══════════════════════════════════════════════════════════════")
	fmt.Println("🔤 Phase 7B: BPE Text Generation")
	fmt.Println("══════════════════════════════════════════════════════════════\n")

	prompts := []string{"fn ", "let ", "// ", "FreeLang", "if "}
	cfgs := []struct {
		cfg  SamplingConfig
		name string
	}{
		{SamplingConfig{"greedy",  1.0, 0, 0,    60}, "Greedy"},
		{SamplingConfig{"topk",    0.8, 20, 0,   60}, "Top-K(20)"},
		{SamplingConfig{"nucleus", 0.9, 0, 0.9,  60}, "Nucleus(0.9)"},
	}

	for _, pr := range prompts {
		promptToks := tok.Encode(pr)
		if len(promptToks) == 0 { continue }

		fmt.Printf("┌─ %q\n", pr)
		for _, c := range cfgs {
			gen := model.Generate(promptToks, c.cfg)
			decoded := tok.Decode(append(promptToks, gen...))
			fmt.Printf("│  [%-14s] %s\n", c.name, cleanOutput(decoded, 80))
		}
		fmt.Println("└──────────────────────────────────────────────────────────")
		fmt.Println()
	}
}

