package main

import (
	"encoding/binary"
	"fmt"
	"math"
	"math/rand"
	"os"
)

// ==================================================
// Phase 8: N-Layer Transformer — End-to-End Backprop
//
// 구조:
//   Embedding [vocab, d]
//   N × TransformerBlock (각 레이어 독립 가중치)
//   Final LN + Proj [d, vocab]
//
// 핵심: Forward 시 레이어 간 activation 연결,
//       Backward 시 dX를 레이어 역순으로 전파
// ==================================================

// ─────────────────────────────────────────────────
// 단일 레이어 가중치
// ─────────────────────────────────────────────────

type NLayerBlock struct {
	Wq, Wk, Wv, Wo    [][]float64
	ln1Scale, ln1Bias  []float64
	W1, W2             [][]float64
	b1, b2             []float64
	ln2Scale, ln2Bias  []float64
}

func newNLayerBlock(d, ffn int) *NLayerBlock {
	scale  := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	return &NLayerBlock{
		Wq: make2DRand(d, d, scale),
		Wk: make2DRand(d, d, scale),
		Wv: make2DRand(d, d, scale),
		Wo: make2DRand(d, d, scale),
		ln1Scale: onesVec(d),
		ln1Bias:  zerosVec(d),
		W1: make2DRand(d, ffn, fScale),
		b1: zerosVec(ffn),
		W2: make2DRand(ffn, d, fScale),
		b2: zerosVec(d),
		ln2Scale: onesVec(d),
		ln2Bias:  zerosVec(d),
	}
}

// ─────────────────────────────────────────────────
// N-Layer 모델
// ─────────────────────────────────────────────────

type NLayerModel struct {
	vocabSize int
	dModel    int
	dFFn      int
	numHeads  int
	dHead     int
	numLayers int

	embedding [][]float64
	blocks    []*NLayerBlock
	lnFScale  []float64 // final LN
	lnFBias   []float64
	proj      [][]float64 // [d, vocab]
}

func newNLayerModel(vocabSize, d, ffn, numHeads, numLayers int) *NLayerModel {
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))
	blocks := make([]*NLayerBlock, numLayers)
	for i := range blocks {
		blocks[i] = newNLayerBlock(d, ffn)
	}
	return &NLayerModel{
		vocabSize: vocabSize,
		dModel:    d,
		dFFn:      ffn,
		numHeads:  numHeads,
		dHead:     d / numHeads,
		numLayers: numLayers,
		embedding: make2DRand(vocabSize, d, vScale),
		blocks:    blocks,
		lnFScale:  onesVec(d),
		lnFBias:   zerosVec(d),
		proj:      make2DRand(d, vocabSize, vScale),
	}
}

// ─────────────────────────────────────────────────
// blockForwardFromX: x [][]float64 입력, BlockCache 반환
// (BPModel의 forwardBP와 동일 로직, embedding 제외)
// ─────────────────────────────────────────────────

func blockForwardFromX(blk *NLayerBlock, x [][]float64, d, ffn, numHeads, dHead int) ([][]float64, *BlockCache) {
	seqLen := len(x)
	nH := numHeads
	dH := dHead

	cache := &BlockCache{X: copyMat(x)}

	// MHA projections
	cache.Q = matmul2D(x, blk.Wq)
	cache.K = matmul2D(x, blk.Wk)
	cache.V = matmul2D(x, blk.Wv)

	// Causal attention per head
	attnOut := make([][]float64, seqLen)
	for i := range attnOut { attnOut[i] = make([]float64, d) }
	cache.AttnWPerHead = make([][][]float64, nH)

	scale := 1.0 / math.Sqrt(float64(dH))
	for h := 0; h < nH; h++ {
		hS := h * dH
		cache.AttnWPerHead[h] = make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			cache.AttnWPerHead[h][i] = make([]float64, seqLen)
		}
		for i := 0; i < seqLen; i++ {
			scores := make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += cache.Q[i][hS+k] * cache.K[j][hS+k]
				}
				scores[j] = dot * scale
			}
			for j := i + 1; j < seqLen; j++ { scores[j] = -1e9 }
			probs := softmax1D(scores)
			copy(cache.AttnWPerHead[h][i], probs)
			for j := 0; j < seqLen; j++ {
				for k := 0; k < dH; k++ {
					attnOut[i][hS+k] += probs[j] * cache.V[j][hS+k]
				}
			}
		}
	}
	cache.AttnOut = attnOut
	cache.MhaOut = matmul2D(attnOut, blk.Wo)

	// Add & LN1
	res1 := make([][]float64, seqLen)
	for i := range res1 { res1[i] = addResidual(x[i], cache.MhaOut[i]) }
	cache.Res1      = res1
	cache.Ln1Mean   = make([]float64, seqLen)
	cache.Ln1InvStd = make([]float64, seqLen)
	cache.Ln1Out    = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln1Out[i], cache.Ln1Mean[i], cache.Ln1InvStd[i] =
			layerNormFull(res1[i], blk.ln1Scale, blk.ln1Bias)
	}

	// FFN (GELU)
	H, HPreact, ffnOut := make([][]float64, seqLen), make([][]float64, seqLen), make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		pre := make([]float64, ffn)
		h   := make([]float64, ffn)
		for j := 0; j < ffn; j++ {
			s := blk.b1[j]
			for k := 0; k < d; k++ { s += cache.Ln1Out[i][k] * blk.W1[k][j] }
			pre[j] = s
			h[j]   = geluActivation(s)
		}
		HPreact[i] = pre
		H[i] = h
		out := make([]float64, d)
		for k := 0; k < d; k++ {
			s := blk.b2[k]
			for j := 0; j < ffn; j++ { s += h[j] * blk.W2[j][k] }
			out[k] = s
		}
		ffnOut[i] = out
	}
	cache.H, cache.HPreact, cache.FfnOut = H, HPreact, ffnOut

	// Add & LN2
	res2 := make([][]float64, seqLen)
	for i := range res2 { res2[i] = addResidual(cache.Ln1Out[i], ffnOut[i]) }
	cache.Res2      = res2
	cache.Ln2Mean   = make([]float64, seqLen)
	cache.Ln2InvStd = make([]float64, seqLen)
	cache.Ln2Out    = make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		cache.Ln2Out[i], cache.Ln2Mean[i], cache.Ln2InvStd[i] =
			layerNormFull(res2[i], blk.ln2Scale, blk.ln2Bias)
	}

	return cache.Ln2Out, cache
}

// ─────────────────────────────────────────────────
// blockBackward: dOutput(seqLen×d) → dInput(seqLen×d)
// 블록 가중치 업데이트 포함, dX 반환
// ─────────────────────────────────────────────────

func blockBackward(
	blk *NLayerBlock,
	cache *BlockCache,
	dOut [][]float64, // gradient w.r.t. block output (Ln2Out)
	adam *BPAdams,
	d, ffn, numHeads, dHead int,
) [][]float64 {
	seqLen := len(dOut)
	nH := numHeads
	dH := dHead

	// ── LN2 backward ─────────────────────────────────────
	dRes2     := make([][]float64, seqLen)
	dLn2Scale := make([]float64, d)
	dLn2Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(dOut[i], cache.Res2[i], blk.ln2Scale, cache.Ln2Mean[i], cache.Ln2InvStd[i])
		dRes2[i] = dx
		for k := range dsc { dLn2Scale[k] += dsc[k]; dLn2Bias[k] += dbs[k] }
	}
	blk.ln2Scale = adam.ln2Scale.Step(blk.ln2Scale, dLn2Scale)
	blk.ln2Bias  = adam.ln2Bias.Step(blk.ln2Bias,  dLn2Bias)

	// residual split: dRes2 → dLn1Out(잔차) + dFfnOut
	dFfnOut         := copyMat(dRes2)
	dLn1OutFromRes2 := copyMat(dRes2)

	// ── FFN backward ─────────────────────────────────────
	flatW2  := flattenEmbedding(blk.W2)
	gradsW2 := make([]float64, ffn*d)
	gradsb2 := make([]float64, d)
	dHidden := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		dHidden[i] = make([]float64, ffn)
		for k := 0; k < d; k++ {
			gradsb2[k] += dFfnOut[i][k]
			for j := 0; j < ffn; j++ {
				gradsW2[j*d+k] += cache.H[i][j] * dFfnOut[i][k]
				dHidden[i][j]  += blk.W2[j][k] * dFfnOut[i][k]
			}
		}
	}
	blk.W2 = unflattenEmbedding(adam.W2.Step(flatW2, ClipGradient(gradsW2, 1.0)), ffn, d)
	blk.b2 = adam.b2.Step(blk.b2, ClipGradient(gradsb2, 1.0))

	flatW1      := flattenEmbedding(blk.W1)
	gradsW1     := make([]float64, d*ffn)
	gradsb1     := make([]float64, ffn)
	dLn1FromFFN := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		dLn1FromFFN[i] = make([]float64, d)
		for j := 0; j < ffn; j++ {
			dg := dHidden[i][j] * geluGrad(cache.HPreact[i][j])
			gradsb1[j] += dg
			for k := 0; k < d; k++ {
				gradsW1[k*ffn+j] += cache.Ln1Out[i][k] * dg
				dLn1FromFFN[i][k] += blk.W1[k][j] * dg
			}
		}
	}
	blk.W1 = unflattenEmbedding(adam.W1.Step(flatW1, ClipGradient(gradsW1, 1.0)), d, ffn)
	blk.b1 = adam.b1.Step(blk.b1, ClipGradient(gradsb1, 1.0))

	dLn1Out := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		dLn1Out[i] = make([]float64, d)
		for k := 0; k < d; k++ {
			dLn1Out[i][k] = dLn1OutFromRes2[i][k] + dLn1FromFFN[i][k]
		}
	}

	// ── LN1 backward ─────────────────────────────────────
	dRes1     := make([][]float64, seqLen)
	dLn1Scale := make([]float64, d)
	dLn1Bias  := make([]float64, d)
	for i := 0; i < seqLen; i++ {
		dx, dsc, dbs := layerNormBackward(dLn1Out[i], cache.Res1[i], blk.ln1Scale, cache.Ln1Mean[i], cache.Ln1InvStd[i])
		dRes1[i] = dx
		for k := range dsc { dLn1Scale[k] += dsc[k]; dLn1Bias[k] += dbs[k] }
	}
	blk.ln1Scale = adam.ln1Scale.Step(blk.ln1Scale, dLn1Scale)
	blk.ln1Bias  = adam.ln1Bias.Step(blk.ln1Bias,  dLn1Bias)

	// residual split: dRes1 → dMhaOut + dX(잔차)
	dMhaOut   := copyMat(dRes1)
	dXFromLN1 := copyMat(dRes1)

	// ── Attention backward ───────────────────────────────
	flatWo  := flattenEmbedding(blk.Wo)
	gradsWo := make([]float64, d*d)
	dAttnOut := make([][]float64, seqLen)
	for i := range dAttnOut { dAttnOut[i] = make([]float64, d) }
	for i := 0; i < seqLen; i++ {
		for k := 0; k < d; k++ {
			for j := 0; j < d; j++ {
				gradsWo[j*d+k] += cache.AttnOut[i][j] * dMhaOut[i][k]
				dAttnOut[i][j] += blk.Wo[j][k] * dMhaOut[i][k]
			}
		}
	}
	blk.Wo = unflattenEmbedding(adam.Wo.Step(flatWo, ClipGradient(gradsWo, 1.0)), d, d)

	dQ := make([][]float64, seqLen)
	dK := make([][]float64, seqLen)
	dV := make([][]float64, seqLen)
	for i := range dQ {
		dQ[i] = make([]float64, d)
		dK[i] = make([]float64, d)
		dV[i] = make([]float64, d)
	}
	attnScale := 1.0 / math.Sqrt(float64(dH))

	for h := 0; h < nH; h++ {
		hS := h * dH
		dAttnWh := make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			dAttnWh[i] = make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += dAttnOut[i][hS+k] * cache.V[j][hS+k]
				}
				dAttnWh[i][j] = dot
			}
		}
		for i := 0; i < seqLen; i++ {
			for j := 0; j <= i; j++ {
				for k := 0; k < dH; k++ {
					dV[j][hS+k] += cache.AttnWPerHead[h][i][j] * dAttnOut[i][hS+k]
				}
			}
		}
		for i := 0; i < seqLen; i++ {
			aw := cache.AttnWPerHead[h][i]
			da := dAttnWh[i]
			dot := 0.0
			for j := 0; j <= i; j++ { dot += aw[j] * da[j] }
			for j := 0; j <= i; j++ {
				dScore := aw[j] * (da[j] - dot) * attnScale
				for k := 0; k < dH; k++ {
					dQ[i][hS+k] += dScore * cache.K[j][hS+k]
					dK[j][hS+k] += dScore * cache.Q[i][hS+k]
				}
			}
		}
	}

	flatWq  := flattenEmbedding(blk.Wq)
	flatWk  := flattenEmbedding(blk.Wk)
	flatWv  := flattenEmbedding(blk.Wv)
	gradsWq := make([]float64, d*d)
	gradsWk := make([]float64, d*d)
	gradsWv := make([]float64, d*d)
	dXFromAttn := make([][]float64, seqLen)
	for i := range dXFromAttn { dXFromAttn[i] = make([]float64, d) }

	for i := 0; i < seqLen; i++ {
		for j := 0; j < d; j++ {
			for k := 0; k < d; k++ {
				gradsWq[j*d+k] += cache.X[i][j] * dQ[i][k]
				gradsWk[j*d+k] += cache.X[i][j] * dK[i][k]
				gradsWv[j*d+k] += cache.X[i][j] * dV[i][k]
				dXFromAttn[i][j] += blk.Wq[j][k]*dQ[i][k] + blk.Wk[j][k]*dK[i][k] + blk.Wv[j][k]*dV[i][k]
			}
		}
	}
	blk.Wq = unflattenEmbedding(adam.Wq.Step(flatWq, ClipGradient(gradsWq, 1.0)), d, d)
	blk.Wk = unflattenEmbedding(adam.Wk.Step(flatWk, ClipGradient(gradsWk, 1.0)), d, d)
	blk.Wv = unflattenEmbedding(adam.Wv.Step(flatWv, ClipGradient(gradsWv, 1.0)), d, d)

	// dX = 잔차(LN1) + Attention 경로
	dX := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		dX[i] = make([]float64, d)
		for k := 0; k < d; k++ {
			dX[i][k] = dXFromLN1[i][k] + dXFromAttn[i][k]
		}
	}
	return dX
}

// ─────────────────────────────────────────────────
// Forward: End-to-End (레이어 간 activation 연결)
// ─────────────────────────────────────────────────

type NLayerFwdResult struct {
	layerCaches []*BlockCache
	embX        [][]float64 // embedding 출력 (positional encoding 포함)
	lnFMean     []float64
	lnFInvStd   float64
	lnFOut      []float64
	logits      []float64
}

func (m *NLayerModel) forwardNL(seq []int) (logits []float64, fwd *NLayerFwdResult) {
	seqLen := len(seq)
	d := m.dModel

	// 1) Embedding + positional encoding
	x := make([][]float64, seqLen)
	for i, tok := range seq {
		x[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(x[i], m.embedding[tok])
		}
		for j := 0; j < d; j += 2 {
			pos   := float64(i)
			denom := math.Pow(10000, float64(j)/float64(d))
			x[i][j] += math.Sin(pos / denom)
			if j+1 < d {
				x[i][j+1] += math.Cos(pos / denom)
			}
		}
	}

	fwd = &NLayerFwdResult{
		layerCaches: make([]*BlockCache, m.numLayers),
		embX:        copyMat(x),
	}

	// 2) N Transformer Blocks (레이어 출력 → 다음 레이어 입력)
	cur := x
	for l, blk := range m.blocks {
		var cache *BlockCache
		cur, cache = blockForwardFromX(blk, cur, d, m.dFFn, m.numHeads, m.dHead)
		fwd.layerCaches[l] = cache
	}

	// 3) Final LN (마지막 위치만)
	last := cur[seqLen-1]
	lnOut, lnMean, lnInvStd := layerNormFull(last, m.lnFScale, m.lnFBias)
	fwd.lnFMean    = []float64{lnMean}
	fwd.lnFInvStd  = lnInvStd
	fwd.lnFOut     = lnOut

	// 4) Proj → logits
	logits = make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		s := 0.0
		for k := 0; k < d; k++ { s += lnOut[k] * m.proj[k][v] }
		logits[v] = s
	}
	fwd.logits = logits
	return
}

// ─────────────────────────────────────────────────
// Backward: chain rule로 레이어 역순 전파
// ─────────────────────────────────────────────────

func (m *NLayerModel) backwardNL(
	seq []int,
	target int,
	fwd *NLayerFwdResult,
	dLogits []float64,
	adams []*BPAdams,
	adamProj *AdamState,
	adamEmb  *AdamState,
	adamLnFS *AdamState,
	adamLnFB *AdamState,
) {
	d       := m.dModel
	seqLen  := len(seq)
	lastPos := seqLen - 1

	// ── proj backward ────────────────────────────────────
	flatProj  := flattenEmbedding(m.proj)
	gradsProj := make([]float64, d*m.vocabSize)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			gradsProj[k*m.vocabSize+v] = fwd.lnFOut[k] * dLogits[v]
		}
	}
	m.proj = unflattenEmbedding(adamProj.Step(flatProj, ClipGradient(gradsProj, 1.0)), d, m.vocabSize)

	dLnFOut := make([]float64, d)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			dLnFOut[k] += m.proj[k][v] * dLogits[v]
		}
	}

	// ── Final LN backward ────────────────────────────────
	// 마지막 레이어 출력의 마지막 위치에 대한 gradient
	lastLayerOut := fwd.layerCaches[m.numLayers-1].Ln2Out
	dFinalLNIn, dLnFS, dLnFB := layerNormBackward(
		dLnFOut,
		lastLayerOut[lastPos],
		m.lnFScale,
		fwd.lnFMean[0],
		fwd.lnFInvStd,
	)
	m.lnFScale = adamLnFS.Step(m.lnFScale, dLnFS)
	m.lnFBias  = adamLnFB.Step(m.lnFBias,  dLnFB)

	// dOut for last block: 마지막 위치만 non-zero
	dLayerOut := make([][]float64, seqLen)
	for i := range dLayerOut { dLayerOut[i] = make([]float64, d) }
	copy(dLayerOut[lastPos], dFinalLNIn)

	// ── 레이어 역순 backward (chain rule) ────────────────
	for l := m.numLayers - 1; l >= 0; l-- {
		dLayerOut = blockBackward(
			m.blocks[l],
			fwd.layerCaches[l],
			dLayerOut,
			adams[l],
			d, m.dFFn, m.numHeads, m.dHead,
		)
	}
	// dLayerOut은 이제 embedding 출력에 대한 gradient

	// ── Embedding backward ───────────────────────────────
	flatEmb  := flattenEmbedding(m.embedding)
	gradsEmb := make([]float64, m.vocabSize*d)
	for pos, tok := range seq {
		if tok >= m.vocabSize { continue }
		for k := 0; k < d; k++ {
			gradsEmb[tok*d+k] += dLayerOut[pos][k]
		}
	}
	m.embedding = unflattenEmbedding(adamEmb.Step(flatEmb, ClipGradient(gradsEmb, 1.0)), m.vocabSize, d)
}

// gradNorm: gradient 벡터 L2 norm
func gradNorm(g []float64) float64 {
	s := 0.0
	for _, v := range g { s += v * v }
	return math.Sqrt(s)
}

// ─────────────────────────────────────────────────
// Adam (NLayerModel용 — 공유 proj/emb/lnF + 레이어별)
// ─────────────────────────────────────────────────

type NLayerOptim struct {
	blocks  []*BPAdams
	proj    *AdamState
	emb     *AdamState
	lnFScale *AdamState
	lnFBias  *AdamState
}

func newNLayerOptim(lr float64, vocabSize, d, ffn, numLayers int) *NLayerOptim {
	blocks := make([]*BPAdams, numLayers)
	for i := range blocks {
		blocks[i] = newBPAdams(lr, vocabSize, d, ffn)
	}
	return &NLayerOptim{
		blocks:   blocks,
		proj:     NewAdamState(lr, d*vocabSize),
		emb:      NewAdamState(lr, vocabSize*d),
		lnFScale: NewAdamState(lr, d),
		lnFBias:  NewAdamState(lr, d),
	}
}

func (o *NLayerOptim) setLR(lr float64) {
	for _, b := range o.blocks { b.setLR(lr) }
	o.proj.LearningRate     = lr
	o.emb.LearningRate      = lr
	o.lnFScale.LearningRate = lr
	o.lnFBias.LearningRate  = lr
}

// ─────────────────────────────────────────────────
// Generate (NLayerModel)
// ─────────────────────────────────────────────────

func (m *NLayerModel) GenerateNL(prompt []int, cfg SamplingConfig) []int {
	ctx := make([]int, len(prompt))
	copy(ctx, prompt)
	generated := []int{}
	maxCtx := 128

	for i := 0; i < cfg.MaxTokens; i++ {
		input := ctx
		if len(input) > maxCtx { input = input[len(input)-maxCtx:] }

		logits, _ := m.forwardNL(input)
		probs := applyTemperature(logits, cfg.Temperature)

		var next int
		switch cfg.Method {
		case "greedy": next = greedySample(probs)
		case "topk":   next = topKSample(probs, cfg.TopK)
		default:       next = nucleusSample(probs, cfg.TopP)
		}
		ctx = append(ctx, next)
		generated = append(generated, next)
	}
	return generated
}

// ─────────────────────────────────────────────────
// 학습 루프 (Phase 8 — End-to-End)
// ─────────────────────────────────────────────────

func trainNLayer() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 8: N-Layer Transformer — End-to-End Backprop         ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	tokens, vocab, err := loadCorpus("data/corpus.txt", 500_000, 500)
	if err != nil {
		fmt.Printf("❌ corpus.txt: %v\n", err)
		return
	}
	fmt.Printf("✅ vocab=%d, tokens=%d\n\n", len(vocab), len(tokens))

	d, ffn, numHeads, numLayers := 128, 512, 4, 4
	vocabSize := len(vocab)
	model := newNLayerModel(vocabSize, d, ffn, numHeads, numLayers)
	optim := newNLayerOptim(0.0003, vocabSize, d, ffn, numLayers)

	params := vocabSize*d + numLayers*(4*d*d+2*d*ffn) + d*vocabSize
	fmt.Printf("✅ d=%d, heads=%d, FFN=%d, layers=%d, params=~%dk\n\n",
		d, numHeads, ffn, numLayers, params/1000)

	epochs      := 15
	batchPerEpoch := 200
	seqLen      := 32
	warmup       := epochs * batchPerEpoch / 10
	total        := epochs * batchPerEpoch
	bestPPL      := math.MaxFloat64
	losses       := []float64{}
	step         := 0

	fmt.Printf("seqLen=%d, epochs=%d, batches/epoch=%d, warmup=%d\n\n",
		seqLen, epochs, batchPerEpoch, warmup)
	fmt.Println("══════════════════════════════════════════════════════════════")

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < batchPerEpoch; batch++ {
			step++
			if len(tokens) <= seqLen+1 { break }
			start  := rand.Intn(len(tokens) - seqLen - 1)
			seq    := tokens[start : start+seqLen]
			target := tokens[start+seqLen]

			// LR warmup + cosine decay
			lr := 0.0003
			if step <= warmup {
				lr = 0.0003 * float64(step) / float64(warmup)
			} else {
				p := float64(step-warmup) / float64(total-warmup)
				lr = 0.0003 * 0.5 * (1 + math.Cos(math.Pi*p))
			}
			optim.setLR(lr)

			// Forward
			logits, fwd := model.forwardNL(seq)
			probs := softmax1D(logits)
			loss  := -math.Log(probs[target] + 1e-10)
			epochLoss += loss

			// dLogits (softmax cross-entropy gradient)
			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if target < len(dLogits) { dLogits[target] -= 1.0 }

			// Backward (end-to-end chain rule)
			model.backwardNL(
				seq, target, fwd, dLogits,
				optim.blocks, optim.proj, optim.emb,
				optim.lnFScale, optim.lnFBias,
			)
		}

		avgLoss := epochLoss / float64(batchPerEpoch)
		ppl     := math.Exp(avgLoss)
		losses   = append(losses, avgLoss)
		mark    := ""
		if ppl < bestPPL { bestPPL = ppl; mark = " ★ best" }
		fmt.Printf("✅ Epoch %02d/%d: loss=%.4f  PPL=%.2f%s\n",
			epoch, epochs, avgLoss, ppl, mark)
	}

	// 결과 요약
	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp  := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 8 End-to-End 결과:\n")
		fmt.Printf("   Initial PPL: %.2f\n", iPPL)
		fmt.Printf("   Final PPL:   %.2f\n", fPPL)
		fmt.Printf("   Best PPL:    %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   개선:        %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   악화:        %.1f%% ⚠️\n\n", -imp)
		}
	}

	// 저장
	savePath := "data/nl_model.bin"
	if err := saveNLModel(model, savePath); err != nil {
		fmt.Printf("⚠️  저장 실패: %v\n", err)
	} else {
		fi, _ := os.Stat(savePath)
		size := int64(0)
		if fi != nil { size = fi.Size() }
		fmt.Printf("💾 N-Layer 모델 저장: %s (%.1f MB)\n\n", savePath, float64(size)/1e6)
	}

	generateNL(model, vocab)
}

// ─────────────────────────────────────────────────
// generateNL: 텍스트 생성 데모
// ─────────────────────────────────────────────────

func generateNL(model *NLayerModel, vocab map[string]int) {
	fmt.Println("══════════════════════════════════════════════════════════════")
	fmt.Println("🔤 Phase 8 Text Generation (End-to-End)")
	fmt.Println("══════════════════════════════════════════════════════════════\n")

	prompts := []string{"fn ", "let ", "// ", "if ", "FreeLang"}
	cfgs := []struct {
		cfg  SamplingConfig
		name string
	}{
		{SamplingConfig{"greedy",  1.0, 0, 0,    60}, "Greedy"},
		{SamplingConfig{"nucleus", 0.9, 0, 0.9,  60}, "Nucleus(p=0.9)"},
		{SamplingConfig{"nucleus", 1.1, 0, 0.95, 60}, "Nucleus(creative)"},
	}

	for _, pr := range prompts {
		promptToks := stringToTokens(pr, vocab)
		if len(promptToks) == 0 { continue }
		fmt.Printf("┌─ %q\n", pr)
		for _, c := range cfgs {
			gen := model.GenerateNL(promptToks, c.cfg)
			full := tokensToString(append(promptToks, gen...), vocab)
			fmt.Printf("│  [%-20s] %s\n", c.name, cleanOutput(full, 80))
		}
		fmt.Println("└──────────────────────────────────────────────────────────")
		fmt.Println()
	}
}

// ─────────────────────────────────────────────────
// 저장 / 로드 (NLayerModel)
// ─────────────────────────────────────────────────

func saveNLModel(m *NLayerModel, path string) error {
	f, err := os.Create(path)
	if err != nil { return err }
	defer f.Close()

	w := &binWriter{f: f}
	w.u32(0x4E4C424D) // "NLBM"
	w.u32(2)          // version 2 (end-to-end)
	w.i32(int32(m.vocabSize))
	w.i32(int32(m.dModel))
	w.i32(int32(m.dFFn))
	w.i32(int32(m.numHeads))
	w.i32(int32(m.numLayers))

	w.mat(m.embedding)
	for _, blk := range m.blocks {
		w.mat(blk.Wq); w.mat(blk.Wk); w.mat(blk.Wv); w.mat(blk.Wo)
		w.vec(blk.ln1Scale); w.vec(blk.ln1Bias)
		w.mat(blk.W1); w.vec(blk.b1)
		w.mat(blk.W2); w.vec(blk.b2)
		w.vec(blk.ln2Scale); w.vec(blk.ln2Bias)
	}
	w.vec(m.lnFScale); w.vec(m.lnFBias)
	w.mat(m.proj)
	return w.err
}

func loadNLModel(path string) (*NLayerModel, error) {
	f, err := os.Open(path)
	if err != nil { return nil, err }
	defer f.Close()

	r := &binReader{f: f}
	magic := r.u32(); ver := r.u32()
	if magic != 0x4E4C424D { return nil, fmt.Errorf("invalid magic: 0x%X", magic) }
	_ = ver

	vocabSize := int(r.i32())
	d         := int(r.i32())
	ffn       := int(r.i32())
	numHeads  := int(r.i32())
	numLayers := int(r.i32())
	if r.err != nil { return nil, r.err }

	m := &NLayerModel{
		vocabSize: vocabSize, dModel: d, dFFn: ffn,
		numHeads: numHeads, dHead: d / numHeads, numLayers: numLayers,
	}
	m.embedding = r.mat(vocabSize, d)
	m.blocks = make([]*NLayerBlock, numLayers)
	for i := range m.blocks {
		blk := &NLayerBlock{}
		blk.Wq = r.mat(d, d); blk.Wk = r.mat(d, d)
		blk.Wv = r.mat(d, d); blk.Wo = r.mat(d, d)
		blk.ln1Scale = r.vec(d); blk.ln1Bias = r.vec(d)
		blk.W1 = r.mat(d, ffn); blk.b1 = r.vec(ffn)
		blk.W2 = r.mat(ffn, d); blk.b2 = r.vec(d)
		blk.ln2Scale = r.vec(d); blk.ln2Bias = r.vec(d)
		m.blocks[i] = blk
	}
	m.lnFScale = r.vec(d); m.lnFBias = r.vec(d)
	m.proj = r.mat(d, vocabSize)
	if r.err != nil { return nil, r.err }
	return m, nil
}

// make2DZeros helper
func make2DZeros(rows, cols int) [][]float64 {
	m := make([][]float64, rows)
	for i := range m { m[i] = make([]float64, cols) }
	return m
}

// binReader.f 타입 호환을 위한 래퍼
var _ = binary.LittleEndian // import 유지

