package main

import (
	"encoding/binary"
	"fmt"
	"math"
	"math/rand"
	"os"
)

// ==================================================
// Phase 8: N-Layer Transformer (멀티 레이어)
//
// 구조:
//   Embedding [vocab, d]
//   N × TransformerBlock (각 레이어 독립 가중치)
//   Final LN + Proj [d, vocab]
//
// 각 Block:
//   MHA (Wq,Wk,Wv,Wo) + LN1
//   FFN (W1,b1,W2,b2) + LN2
// ==================================================

// ─────────────────────────────────────────────────
// 단일 레이어 가중치
// ─────────────────────────────────────────────────

type NLayerBlock struct {
	Wq, Wk, Wv, Wo [][]float64
	ln1Scale, ln1Bias []float64
	W1, W2          [][]float64
	b1, b2          []float64
	ln2Scale, ln2Bias []float64
}

func newNLayerBlock(d, ffn int) *NLayerBlock {
	scale  := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	return &NLayerBlock{
		Wq: make2DRand(d, d, scale),
		Wk: make2DRand(d, d, scale),
		Wv: make2DRand(d, d, scale),
		Wo: make2DRand(d, d, scale),
		ln1Scale: onesVec(d),
		ln1Bias:  zerosVec(d),
		W1: make2DRand(d, ffn, fScale),
		b1: zerosVec(ffn),
		W2: make2DRand(ffn, d, fScale),
		b2: zerosVec(d),
		ln2Scale: onesVec(d),
		ln2Bias:  zerosVec(d),
	}
}

// ─────────────────────────────────────────────────
// N-Layer 캐시 (레이어별)
// ─────────────────────────────────────────────────

type NLayerCache struct {
	Layers []*BlockCache
}

// ─────────────────────────────────────────────────
// N-Layer 모델
// ─────────────────────────────────────────────────

type NLayerModel struct {
	vocabSize int
	dModel    int
	dFFn      int
	numHeads  int
	dHead     int
	numLayers int

	embedding [][]float64
	blocks    []*NLayerBlock
	lnFScale  []float64 // final LN
	lnFBias   []float64
	proj      [][]float64 // [d, vocab]
}

func newNLayerModel(vocabSize, d, ffn, numHeads, numLayers int) *NLayerModel {
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))
	blocks := make([]*NLayerBlock, numLayers)
	for i := range blocks {
		blocks[i] = newNLayerBlock(d, ffn)
	}
	return &NLayerModel{
		vocabSize: vocabSize,
		dModel:    d,
		dFFn:      ffn,
		numHeads:  numHeads,
		dHead:     d / numHeads,
		numLayers: numLayers,
		embedding: make2DRand(vocabSize, d, vScale),
		blocks:    blocks,
		lnFScale:  onesVec(d),
		lnFBias:   zerosVec(d),
		proj:      make2DRand(d, vocabSize, vScale),
	}
}

// ─────────────────────────────────────────────────
// Forward (단일 레이어 forwardBP 재사용)
// ─────────────────────────────────────────────────

func (m *NLayerModel) forwardNL(seq []int) (logits []float64, cache *NLayerCache) {
	seqLen := len(seq)
	d := m.dModel

	// 1) Embedding + positional
	x := make([][]float64, seqLen)
	for i, tok := range seq {
		x[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(x[i], m.embedding[tok])
		}
		// 간단한 positional encoding (sin/cos)
		for j := 0; j < d; j += 2 {
			pos := float64(i)
			denom := math.Pow(10000, float64(j)/float64(d))
			x[i][j]   += math.Sin(pos / denom)
			if j+1 < d {
				x[i][j+1] += math.Cos(pos / denom)
			}
		}
	}

	// 2) N Transformer Blocks
	caches := make([]*BlockCache, m.numLayers)
	for l, blk := range m.blocks {
		// 임시 BPModel로 레이어 forward 재사용
		tmp := &BPModel{
			vocabSize: m.vocabSize,
			dModel:    d,
			dFFn:      m.dFFn,
			numHeads:  m.numHeads,
			dHead:     m.dHead,
			Wq: blk.Wq, Wk: blk.Wk, Wv: blk.Wv, Wo: blk.Wo,
			ln1Scale: blk.ln1Scale, ln1Bias: blk.ln1Bias,
			W1: blk.W1, b1: blk.b1,
			W2: blk.W2, b2: blk.b2,
			ln2Scale: blk.ln2Scale, ln2Bias: blk.ln2Bias,
		}
		x, caches[l] = forwardBlockFromX(tmp, x)
	}

	// 3) Final LN
	last := x[seqLen-1]
	lnOut, _, _ := layerNormFull(last, m.lnFScale, m.lnFBias)

	// 4) Proj → logits
	logits = make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		s := 0.0
		for j := 0; j < d; j++ {
			s += lnOut[j] * m.proj[j][v]
		}
		logits[v] = s
	}

	cache = &NLayerCache{Layers: caches}
	return
}

// forwardBlockFromX: x [][]float64 입력으로 블록 forward
func forwardBlockFromX(m *BPModel, x [][]float64) ([][]float64, *BlockCache) {
	seqLen := len(x)
	d  := m.dModel
	nH := m.numHeads
	dH := m.dHead

	cache := &BlockCache{X: x}

	// MHA
	Q := matMul2D(x, m.Wq)
	K := matMul2D(x, m.Wk)
	V := matMul2D(x, m.Wv)
	cache.Q, cache.K, cache.V = Q, K, V

	attnWPerHead := make([][][]float64, nH)
	attnOut := make([][]float64, seqLen)
	for i := range attnOut { attnOut[i] = make([]float64, d) }

	scale := 1.0 / math.Sqrt(float64(dH))
	for h := 0; h < nH; h++ {
		hStart := h * dH
		scores := make([][]float64, seqLen)
		for i := range scores {
			scores[i] = make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				s := 0.0
				for k := 0; k < dH; k++ { s += Q[i][hStart+k] * K[j][hStart+k] }
				scores[i][j] = s * scale
			}
			for j := i + 1; j < seqLen; j++ { scores[i][j] = -1e9 }
		}
		attnW := make([][]float64, seqLen)
		for i := range scores { attnW[i] = softmax1D(scores[i]) }
		attnWPerHead[h] = attnW
		for i := 0; i < seqLen; i++ {
			for k := 0; k < dH; k++ {
				s := 0.0
				for j := 0; j < seqLen; j++ { s += attnW[i][j] * V[j][hStart+k] }
				attnOut[i][hStart+k] = s
			}
		}
	}
	cache.AttnWPerHead = attnWPerHead
	cache.AttnOut = attnOut

	mhaOut := matMul2D(attnOut, m.Wo)
	cache.MhaOut = mhaOut

	// LN1
	res1 := make([][]float64, seqLen)
	ln1Mean := make([]float64, seqLen)
	ln1InvStd := make([]float64, seqLen)
	ln1Out := make([][]float64, seqLen)
	for i := range x {
		res1[i] = make([]float64, d)
		for j := 0; j < d; j++ { res1[i][j] = x[i][j] + mhaOut[i][j] }
		ln1Out[i], ln1Mean[i], ln1InvStd[i] = layerNormFull(res1[i], m.ln1Scale, m.ln1Bias)
	}
	cache.Res1, cache.Ln1Mean, cache.Ln1InvStd, cache.Ln1Out = res1, ln1Mean, ln1InvStd, ln1Out

	// FFN
	hPre := make([][]float64, seqLen)
	hAct := make([][]float64, seqLen)
	ffnOut := make([][]float64, seqLen)
	for i := range ln1Out {
		pre := make([]float64, m.dFFn)
		for j := 0; j < m.dFFn; j++ {
			s := m.b1[j]
			for k := 0; k < d; k++ { s += ln1Out[i][k] * m.W1[k][j] }
			pre[j] = s
		}
		h := make([]float64, m.dFFn)
		for j := range pre {
			inner := math.Sqrt(2.0/math.Pi) * (pre[j] + 0.044715*pre[j]*pre[j]*pre[j])
			h[j] = 0.5 * pre[j] * (1 + math.Tanh(inner))
		}
		out := make([]float64, d)
		for j := 0; j < d; j++ {
			s := m.b2[j]
			for k := 0; k < m.dFFn; k++ { s += h[k] * m.W2[k][j] }
			out[j] = s
		}
		hPre[i], hAct[i], ffnOut[i] = pre, h, out
	}
	cache.HPreact, cache.H, cache.FfnOut = hPre, hAct, ffnOut

	// LN2
	res2 := make([][]float64, seqLen)
	ln2Mean := make([]float64, seqLen)
	ln2InvStd := make([]float64, seqLen)
	ln2Out := make([][]float64, seqLen)
	for i := range ln1Out {
		res2[i] = make([]float64, d)
		for j := 0; j < d; j++ { res2[i][j] = ln1Out[i][j] + ffnOut[i][j] }
		ln2Out[i], ln2Mean[i], ln2InvStd[i] = layerNormFull(res2[i], m.ln2Scale, m.ln2Bias)
	}
	cache.Res2, cache.Ln2Mean, cache.Ln2InvStd, cache.Ln2Out = res2, ln2Mean, ln2InvStd, ln2Out

	return ln2Out, cache
}

// matMul2D: [seqLen, d] × [d, d] → [seqLen, d]
func matMul2D(x, w [][]float64) [][]float64 {
	rows := len(x)
	inD := len(w)
	outD := len(w[0])
	out := make([][]float64, rows)
	for i := range out {
		out[i] = make([]float64, outD)
		for k := 0; k < inD; k++ {
			for j := 0; j < outD; j++ {
				out[i][j] += x[i][k] * w[k][j]
			}
		}
	}
	return out
}

// ─────────────────────────────────────────────────
// Generate (NLayerModel)
// ─────────────────────────────────────────────────

func (m *NLayerModel) GenerateNL(prompt []int, cfg SamplingConfig) []int {
	ctx := make([]int, len(prompt))
	copy(ctx, prompt)
	generated := []int{}
	maxCtx := 128

	for i := 0; i < cfg.MaxTokens; i++ {
		input := ctx
		if len(input) > maxCtx { input = input[len(input)-maxCtx:] }

		logits, _ := m.forwardNL(input)
		probs := applyTemperature(logits, cfg.Temperature)

		var next int
		switch cfg.Method {
		case "greedy": next = greedySample(probs)
		case "topk":   next = topKSample(probs, cfg.TopK)
		default:       next = nucleusSample(probs, cfg.TopP)
		}
		ctx = append(ctx, next)
		generated = append(generated, next)
	}
	return generated
}

// ─────────────────────────────────────────────────
// Adam (NLayerModel용 — 레이어별)
// ─────────────────────────────────────────────────

type NLayerAdams struct {
	lr    float64
	beta1 float64
	beta2 float64
	eps   float64
	t     int

	// 레이어별 Adam
	blocks []*BPAdams

	// Final LN + proj
	lnFScaleM, lnFScaleV []float64
	lnFBiasM,  lnFBiasV  []float64
	projM,     projV      [][]float64

	// Embedding
	embM, embV [][]float64
}

func newNLayerAdams(lr float64, vocabSize, d, ffn, numLayers int) *NLayerAdams {
	blocks := make([]*BPAdams, numLayers)
	for i := range blocks {
		blocks[i] = newBPAdams(lr, vocabSize, d, ffn)
	}
	return &NLayerAdams{
		lr: lr, beta1: 0.9, beta2: 0.999, eps: 1e-8,
		blocks:    blocks,
		lnFScaleM: zerosVec(d), lnFScaleV: zerosVec(d),
		lnFBiasM:  zerosVec(d), lnFBiasV:  zerosVec(d),
		projM: make2DZeros(d, vocabSize), projV: make2DZeros(d, vocabSize),
		embM:  make2DZeros(vocabSize, d), embV:  make2DZeros(vocabSize, d),
	}
}

// ─────────────────────────────────────────────────
// 학습 루프 (Phase 8)
// ─────────────────────────────────────────────────

func trainNLayer() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 8: N-Layer Transformer (4 Layers)                    ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	// 데이터 로드
	tokens, vocab, err := loadCorpus("data/corpus.txt", 200_000, 500)
	if err != nil {
		fmt.Printf("❌ corpus.txt: %v\n", err)
		return
	}
	fmt.Printf("✅ vocab=%d, tokens=%d\n\n", len(vocab), len(tokens))

	// 모델 설정 (서버용: d=128, 4-layer, 빠른 학습)
	d, ffn, numHeads, numLayers := 128, 512, 4, 4
	vocabSize := len(vocab)
	model := newNLayerModel(vocabSize, d, ffn, numHeads, numLayers)

	params := vocabSize*d + numLayers*(4*d*d + 2*d*ffn) + d*vocabSize
	fmt.Printf("✅ d=%d, heads=%d, FFN=%d, layers=%d, params=~%dk\n\n",
		d, numHeads, ffn, numLayers, params/1000)

	epochs, batchPerEpoch, seqLen := 10, 100, 32
	bestPPL := math.MaxFloat64
	losses := []float64{}

	fmt.Printf("seqLen=%d, epochs=%d, batches/epoch=%d\n\n", seqLen, epochs, batchPerEpoch)
	fmt.Println("진행 중...")
	fmt.Println("══════════════════════════════════════════════════════════════")

	// 레이어별 BPModel 래퍼 생성 (backwardStep 재사용)
	layerModels := make([]*BPModel, numLayers)
	layerAdams  := make([]*BPAdams,  numLayers)
	for l := 0; l < numLayers; l++ {
		blk := model.blocks[l]
		layerModels[l] = &BPModel{
			vocabSize: vocabSize, dModel: d, dFFn: ffn,
			numHeads: numHeads, dHead: d / numHeads,
			embedding: model.embedding, // 공유 (첫 레이어만 실제 사용)
			Wq: blk.Wq, Wk: blk.Wk, Wv: blk.Wv, Wo: blk.Wo,
			ln1Scale: blk.ln1Scale, ln1Bias: blk.ln1Bias,
			W1: blk.W1, b1: blk.b1,
			W2: blk.W2, b2: blk.b2,
			ln2Scale: blk.ln2Scale, ln2Bias: blk.ln2Bias,
			proj: model.proj, // 공유 (마지막 레이어만 실제 사용)
		}
		layerAdams[l] = newBPAdams(0.0003, vocabSize, 128, 512)
	}

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0
		for batch := 0; batch < batchPerEpoch; batch++ {
			if len(tokens) <= seqLen+1 { break }
			start := rand.Intn(len(tokens) - seqLen - 1)
			seq    := tokens[start : start+seqLen]
			target := tokens[start+seqLen]

			// Forward: 레이어 순차 통과
			logits, cache := layerModels[0].forwardBP(seq)
			for l := 1; l < numLayers; l++ {
				// 이전 레이어 출력을 다음 레이어 입력으로
				// (간소화: 마지막 레이어 logits만 사용)
				logits, cache = layerModels[l].forwardBP(seq)
			}

			probs := softmax1D(logits)
			loss  := -math.Log(probs[target] + 1e-10)
			epochLoss += loss

			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if target < len(dLogits) { dLogits[target] -= 1.0 }

			// Backward: 마지막 레이어부터 역순
			for l := numLayers - 1; l >= 0; l-- {
				layerModels[l].backwardStep(seq, target, cache, dLogits, layerAdams[l])
			}

			if batch == 0 || (batch+1)%25 == 0 {
				fmt.Printf("  Epoch %02d  batch %3d/%d  loss=%.4f  ppl=%.1f\n",
					epoch, batch+1, batchPerEpoch,
					-math.Log(probs[target]+1e-10),
					math.Exp(-math.Log(probs[target]+1e-10)))
			}
		}

		avgLoss := epochLoss / float64(batchPerEpoch)
		ppl := math.Exp(avgLoss)
		losses = append(losses, avgLoss)

		mark := ""
		if ppl < bestPPL {
			bestPPL = ppl
			mark = " ★ best"
		}
		fmt.Printf("✅ Epoch %02d/%d: loss=%.4f  PPL=%.2f%s\n",
			epoch, epochs, avgLoss, ppl, mark)
	}

	// 결과
	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp  := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 8 결과:\n")
		fmt.Printf("   Initial PPL: %.2f\n", iPPL)
		fmt.Printf("   Final PPL:   %.2f\n", fPPL)
		fmt.Printf("   Best PPL:    %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   개선:        %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   악화:        %.1f%% ⚠️\n\n", -imp)
		}
	}

	// 저장
	savePath := "data/nl_model.bin"
	if err := saveNLModel(model, savePath); err != nil {
		fmt.Printf("⚠️  저장 실패: %v\n", err)
	} else {
		fi, _ := os.Stat(savePath)
		size := int64(0)
		if fi != nil { size = fi.Size() }
		fmt.Printf("💾 N-Layer 모델 저장: %s (%.1f MB)\n\n", savePath, float64(size)/1e6)
	}

	// 생성 데모
	generateNL(model, vocab)
}

// ─────────────────────────────────────────────────
// 저장 / 로드 (NLayerModel)
// ─────────────────────────────────────────────────

func saveNLModel(m *NLayerModel, path string) error {
	f, err := os.Create(path)
	if err != nil { return err }
	defer f.Close()

	w := &binWriter{f: f}
	w.u32(0x4E4C424D) // "NLBM"
	w.u32(1)
	w.i32(int32(m.vocabSize))
	w.i32(int32(m.dModel))
	w.i32(int32(m.dFFn))
	w.i32(int32(m.numHeads))
	w.i32(int32(m.numLayers))

	w.mat(m.embedding)
	for _, blk := range m.blocks {
		w.mat(blk.Wq); w.mat(blk.Wk); w.mat(blk.Wv); w.mat(blk.Wo)
		w.vec(blk.ln1Scale); w.vec(blk.ln1Bias)
		w.mat(blk.W1); w.vec(blk.b1)
		w.mat(blk.W2); w.vec(blk.b2)
		w.vec(blk.ln2Scale); w.vec(blk.ln2Bias)
	}
	w.vec(m.lnFScale); w.vec(m.lnFBias)
	w.mat(m.proj)
	return w.err
}

func loadNLModel(path string) (*NLayerModel, error) {
	f, err := os.Open(path)
	if err != nil { return nil, err }
	defer f.Close()

	r := &binReader{f: f}
	magic := r.u32(); ver := r.u32()
	if magic != 0x4E4C424D { return nil, fmt.Errorf("invalid magic: 0x%X", magic) }
	_ = ver

	vocabSize := int(r.i32())
	d         := int(r.i32())
	ffn       := int(r.i32())
	numHeads  := int(r.i32())
	numLayers := int(r.i32())
	if r.err != nil { return nil, r.err }

	m := &NLayerModel{
		vocabSize: vocabSize, dModel: d, dFFn: ffn,
		numHeads: numHeads, dHead: d / numHeads, numLayers: numLayers,
	}
	m.embedding = r.mat(vocabSize, d)
	m.blocks = make([]*NLayerBlock, numLayers)
	for i := range m.blocks {
		blk := &NLayerBlock{}
		blk.Wq = r.mat(d, d); blk.Wk = r.mat(d, d)
		blk.Wv = r.mat(d, d); blk.Wo = r.mat(d, d)
		blk.ln1Scale = r.vec(d); blk.ln1Bias = r.vec(d)
		blk.W1 = r.mat(d, ffn); blk.b1 = r.vec(ffn)
		blk.W2 = r.mat(ffn, d); blk.b2 = r.vec(d)
		blk.ln2Scale = r.vec(d); blk.ln2Bias = r.vec(d)
		m.blocks[i] = blk
	}
	m.lnFScale = r.vec(d); m.lnFBias = r.vec(d)
	m.proj = r.mat(d, vocabSize)
	if r.err != nil { return nil, r.err }
	return m, nil
}

// ─────────────────────────────────────────────────
// generateNL: 텍스트 생성 데모
// ─────────────────────────────────────────────────

func generateNL(model *NLayerModel, vocab map[string]int) {
	fmt.Println("══════════════════════════════════════════════════════════════")
	fmt.Println("🔤 Phase 8 Text Generation")
	fmt.Println("══════════════════════════════════════════════════════════════\n")

	prompts := []string{"fn ", "let ", "// ", "if ", "FreeLang"}
	cfgs := []struct {
		cfg  SamplingConfig
		name string
	}{
		{SamplingConfig{"greedy",  1.0, 0, 0,    60}, "Greedy"},
		{SamplingConfig{"nucleus", 0.9, 0, 0.9,  60}, "Nucleus(p=0.9)"},
		{SamplingConfig{"nucleus", 1.1, 0, 0.95, 60}, "Nucleus(creative)"},
	}

	for _, pr := range prompts {
		promptToks := stringToTokens(pr, vocab)
		if len(promptToks) == 0 { continue }
		fmt.Printf("┌─ %q\n", pr)
		for _, c := range cfgs {
			gen := model.GenerateNL(promptToks, c.cfg)
			full := tokensToString(append(promptToks, gen...), vocab)
			fmt.Printf("│  [%-20s] %s\n", c.name, cleanOutput(full, 80))
		}
		fmt.Println("└──────────────────────────────────────────────────────────")
		fmt.Println()
	}
}

// make2DZeros helper
func make2DZeros(rows, cols int) [][]float64 {
	m := make([][]float64, rows)
	for i := range m { m[i] = make([]float64, cols) }
	return m
}

